refused_program.body:
set -eu
export GIT_EDITOR=true GIT_MERGE_AUTOEDIT=no
git fetch --no-tags {upstream_remote} {upstream_branch}
if git merge --no-edit --no-ff {upstream_remote}/{upstream_branch}; then
  exit 0
fi
tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT
git diff --name-only --diff-filter=U -z > "$tmp/conflicted"
if [ ! -s "$tmp/conflicted" ]; then
  git merge --abort >/dev/null 2>&1 || true
  exit 1
fi
mb=$(git merge-base HEAD MERGE_HEAD)
while IFS= read -r -d '' f; do
  if ! git cat-file -e "HEAD:$f" 2>/dev/null; then
    git rm -q --ignore-unmatch -- "$f"
    continue
  fi
  if ! git cat-file -e "MERGE_HEAD:$f" 2>/dev/null || ! git cat-file -e "$mb:$f" 2>/dev/null; then
    git checkout --ours -- "$f" 2>/dev/null || true
    git add -- "$f"
    continue
  fi
  git show "HEAD:$f" > "$tmp/ours"
  git show "MERGE_HEAD:$f" > "$tmp/theirs"
  git diff -U0 --no-color "$mb" MERGE_HEAD -- "$f" > "$tmp/patch"
  OURS="$tmp/ours" THEIRS="$tmp/theirs" awk '
    BEGIN {
      while ((getline line < ENVIRON["OURS"]) > 0) {
        O[++nO] = line
        if (!(line in firstO)) firstO[line] = nO
      }
      close(ENVIRON["OURS"])
      while ((getline line < ENVIRON["THEIRS"]) > 0) T[++nT] = line
      close(ENVIRON["THEIRS"])
    }
    /^@@/ { nh++; na[nh] = 0; nd[nh] = 0; next }
    /^-/ && !/^---/ { nd[nh]++; next }
    /^\+/ && !/^\+\+\+/ { A[nh, ++na[nh]] = substr($0, 2); next }
    END {
      ni = 0
      for (h = 1; h <= nh; h++) {
        if (na[h] > nd[h]) {
          for (k = 1; k <= na[h]; k++) {
            ins[++ni] = A[h, k]
            isins[A[h, k]] = 1
          }
        }
      }
      for (i = 1; i <= ni; i++) {
        s = ins[i]
        idx = 0
        for (j = 1; j <= nT; j++) if (T[j] == s && j > used[s]) { idx = j; break }
        if (idx == 0) for (j = 1; j <= nT; j++) if (T[j] == s) { idx = j; break }
        used[s] = idx
        tgt[i] = 0
        md[i] = "end"
        for (j = idx - 1; j >= 1; j--) {
          if (T[j] in isins) continue
          if (T[j] in firstO) { tgt[i] = firstO[T[j]]; md[i] = "after"; break }
        }
        if (tgt[i] == 0) {
          for (j = idx + 1; j <= nT; j++) {
            if (T[j] in isins) continue
            if (T[j] in firstO) { tgt[i] = firstO[T[j]]; md[i] = "before"; break }
          }
        }
      }
      for (i = 1; i <= nO; i++) {
        for (k = 1; k <= ni; k++) if (md[k] == "before" && tgt[k] == i) print ins[k]
        print O[i]
        for (k = 1; k <= ni; k++) if (md[k] == "after" && tgt[k] == i) print ins[k]
      }
      for (k = 1; k <= ni; k++) if (md[k] == "end") print ins[k]
    }
  ' "$tmp/patch" > "$tmp/merged"
  cat "$tmp/merged" > "$f"
  git add -- "$f"
done < "$tmp/conflicted"
git commit --no-edit >/dev/null

postconditions.probe:
mb=$(git merge-base HEAD^1 HEAD^2)
bad=0
while IFS= read -r f; do
  [ -n "$f" ] || continue
  git cat-file -e "$mb:$f" 2>/dev/null || continue
  while IFS= read -r line; do
    [ -n "$line" ] || continue
    git show "HEAD:$f" 2>/dev/null | grep -Fqx -- "$line" || bad=1
  done < <(git diff -U0 --no-color "$mb" HEAD^2 -- "$f" | awk '
    /^@@/ { if (h) flush(); h = 1; next }
    /^-/ && !/^---/ { nd++; next }
    /^\+/ && !/^\+\+\+/ { A[++na] = substr($0, 2); next }
    END { if (h) flush() }
    function flush() {
      if (na > nd) for (i = 1; i <= na; i++) print A[i]
      na = 0; nd = 0
    }
  ')
done < <(git diff --name-only -z "$mb" HEAD^2 | tr '\0' '\n' | sort)
[ "$bad" -eq 0 ]
